//go:build detector_bridge

package coupling

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"encoding/json"
	"io"
)

func literalOracleBridgeExpectations() map[string]oracleBridgeVector {
	return decodeLiteralOracleBridgeVectors(literalOracleBridgeGZIP)
}

func decodeLiteralOracleBridgeVectors(encoded string) map[string]oracleBridgeVector {
	compressed, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		panic("invalid literal oracle bridge vectors")
	}
	reader, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		panic("invalid literal oracle bridge gzip")
	}
	data, err := io.ReadAll(reader)
	if err != nil {
		panic("invalid literal oracle bridge data")
	}
	if err := reader.Close(); err != nil {
		panic("invalid literal oracle bridge gzip close")
	}
	var expected map[string]oracleBridgeVector
	if err := json.Unmarshal(data, &expected); err != nil {
		panic("invalid literal oracle bridge JSON")
	}
	return expected
}

